import {scanSignals} from './signals-core.mjs';
import {compareReports} from './report-links.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function signalDesk({getWorkspace,today,feedback}) {
  let settings={terms:'',mode:'any',from:'2026-10-01',to:today(),minGroups:2,scope:'All'},report=null,comparison=null,comparisonWindow=null;
  const passage=r=>`<div class="report-passage"><p class="small-label">${esc(r.id)} / ${r.synthetic?'SYNTHETIC':'ANALYST-ENTERED / UNVERIFIED'}</p><h4>${esc(r.title)}</h4><p>${esc(r.caseTitle)} · ${esc(r.scope)} / ${esc(r.area)}</p><p class="muted">${esc(r.publisher)} · Reported ${r.reportedAt} · Recorded ${r.recordedAt}<br>Group: ${esc(r.originGroup)} · ${esc(r.claimState)} / ${esc(r.relation)}</p><blockquote class="source-excerpt">${esc(r.text)}</blockquote>${r.locator?`<p>Locator: ${esc(r.locator)}</p>`:''}${r.accessNote?`<p>Source conditions: ${esc(r.accessNote)}</p>`:''}${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open source reference (unverified)</a>`:''}<button data-task-case="${esc(r.assessmentId)}">View assessment</button></div>`;
  function connections(){
    const target=document.getElementById('report-connections');if(!target)return;
    if(!comparison){target.innerHTML='<p class="empty">Compare retained reports using the date window and scope above. Literal query terms and source-group thresholds do not filter this comparison.</p>';return;}
    target.innerHTML=`<div class="notice"><strong>${comparison.qualifyingPairs} qualifying passage pairs</strong><p>${comparison.comparedRecords} of ${comparison.eligibleRecords} eligible records compared · ${comparison.pairsEvaluated} pairs evaluated · ${comparison.excludedRecords} records excluded by the newest-200 limit.</p><p>Applied window: ${comparison.window.from} to ${comparison.window.to} / ${esc(comparison.window.scope)}. TF-IDF cosine ≥ ${comparison.minSimilarity.toFixed(2)}, at least three shared tokens. This is a lexical review aid, not event identity or a threat probability.</p></div>${comparison.pairs.length?`<p class="muted">Showing the first ${Math.min(10,comparison.pairs.length)} of ${comparison.qualifyingPairs} qualifying pairs, ranked by shared language. Inspect negation, dates and source dependence.</p>${comparison.pairs.slice(0,10).map((p,i)=>`<article class="signal-card"><div class="case-heading"><h3>${esc(p.left.title)} / ${esc(p.right.title)}</h3><span class="chip">Cosine ${p.similarity.toFixed(3)}</span></div><p>${p.sameRecordedGroup?'Same recorded source group: repetition is not independent corroboration.':'Different recorded group labels: independence remains unverified.'} ${p.crossCase?'Reports belong to different cases; no common actor or cause is inferred.':''}</p><p>Shared weighted terms: ${p.sharedTerms.map(esc).join(', ')}${p.sharedTermCount>p.sharedTerms.length?` · ${p.sharedTermCount} shared tokens total`:''}</p><details${i===0?' open':''}><summary>Compare full original passages</summary><div class="report-pair">${passage(p.left)}${passage(p.right)}</div></details><button data-report-link-followup="${esc(p.left.recordKey)}" data-report-link-right="${esc(p.right.recordKey)}">Prepare linkage verification task</button></article>`).join('')}`:'<p class="empty">No pairs pass these lexical settings. This does not establish absence of a threat or absence of related reports.</p>'}<details><summary>Comparison limits</summary>${comparison.limitations.map(t=>`<p>${esc(t)}</p>`).join('')}</details>`;
  }
  function result() {
    const target=document.getElementById('signal-results');if(!target)return;
    if(!report){target.innerHTML='<p class="empty">Define the terms and date window, then run the query. No source is fetched and no AI is called.</p>';return;}
    target.innerHTML=`<div class="notice"><strong>${report.matches.length} matching records · ${report.cases.length} case(s) · ${report.cases.filter(c=>c.thresholdMet).length} case(s) meeting the recorded source-group threshold</strong><p>Applied query: ${report.query.terms.map(esc).join(", ")} · ${report.query.mode} term(s) · ${report.query.from} to ${report.query.to} · ${esc(report.query.scope)} · threshold ${report.query.minGroups} recorded group(s).</p><p>${report.recordsScanned} current records scanned. Matching text is a review lead; negated and benign statements can match.</p></div>${report.cases.length?`<h3>Case triage</h3>${report.cases.map(c=>`<article class="signal-card"><div class="case-heading"><div><p class="small-label">${esc(c.scope)} / ${esc(c.area)}</p><h3>${esc(c.title)}</h3></div><span class="chip">${c.thresholdMet?'Review threshold met':'Below review threshold'}</span></div><p>${c.recordCount} matched records · ${c.sourceGroupCount} recorded source groups · ${c.challengingCount} challenging records</p><p class="muted">Reposts sharing a group count once. Inspect the original context and seek independent confirmation.</p><div class="actions"><button data-task-case="${esc(c.assessmentId)}">View assessment</button><button data-signal-followup="${esc(c.assessmentId)}">Prepare verification task</button></div></article>`).join('')}`:'<p class="empty">No records match these literal terms and dates. This does not establish absence of a threat.</p>'}${report.sourceGroups.some(g=>g.assessmentIds.length>1)?`<h3>Shared reporting across cases</h3>${report.sourceGroups.filter(g=>g.assessmentIds.length>1).map(g=>`<p>Recorded group <strong>${esc(g.label)}</strong>: ${g.assessmentIds.length} cases, records ${g.recordIds.map(esc).join(', ')}. This identifies shared reporting labels, not a common actor or cause.</p>`).join('')}`:''}${report.matches.length?`<h3>Exact matches & source context</h3><p class="muted">Showing the first ${Math.min(50,report.matches.length)} of ${report.matches.length} matched records. Narrow the query to inspect further results.</p>${report.matches.slice(0,50).map(r=>`<article class="signal-card"><p class="small-label">${esc(r.recordId)} / ${r.reportedAt}${r.synthetic?' / SYNTHETIC':''}</p><h3>${esc(r.title)}</h3><p class="muted">${esc(r.caseTitle)} · ${esc(r.publisher)} · Group ${esc(r.originGroup)} · Recorded ${r.recordedAt}</p><div class="tags"><span class="tag">${r.kind==='source_excerpt'?'Retained source excerpt':'Analyst statement'}</span><span class="tag">${esc(r.claimState)}</span><span class="tag">${esc(r.relation)}</span></div><p>${r.hits.map(h=>`<strong>${esc(h.term)}</strong>: ${h.spans.map(s=>`“${esc(s.quote)}” [${s.start}, ${s.end})`).join('; ')+(h.count>h.spans.length?` (${h.count} occurrences; first ${h.spans.length} shown)`:'')}`).join(' · ')}</p><blockquote class="source-excerpt">${esc(r.text)}</blockquote>${r.locator?`<p>Locator: ${esc(r.locator)}</p>`:''}${r.accessNote?`<p>Retained source conditions: ${esc(r.accessNote)}</p>`:''}${r.sourceURL?`<a href="${esc(r.sourceURL)}" target="_blank" rel="noopener noreferrer">Open source reference (unverified)</a>`:''}<p class="muted">Read the full context: a phrase can describe an allegation, a denial, or ordinary activity. Offsets are UTF-16 positions in the displayed original text.</p></article>`).join('')}`:''}<details><summary>Detection limits</summary>${report.limitations.map(t=>`<p>${esc(t)}</p>`).join('')}</details>`;
  }
  function render() {
    // Every visit reruns against current applied input. Nothing is retained as
    // an authoritative alert or copied into case evidence automatically.
    if(report)report=scanSignals(getWorkspace(),settings);
    if(comparison)comparison=compareReports(getWorkspace(),comparisonWindow);
    document.getElementById('content').innerHTML=`<section class="panel"><div class="panel-heading"><div><h2>Indicator triage</h2><span class="muted">Explicit rules · source context · analyst verification</span></div><button id="signal-scenario">Load fictional regional exercise</button></div><div class="case-body"><p>Flag literal report mentions for analyst review. Trace matching passages to their recorded sources, compare cases and prepare follow-up work.</p><p class="notice">Research prototype. This query does not classify intent, attribute actors or predict attacks. Synthetic demonstrations do not establish real-world detection performance.</p><form id="signal-form"><label for="signal-terms">Literal indicator terms (comma separated)</label><input id="signal-terms" value="${esc(settings.terms)}" maxlength="648" placeholder="Example: incident, attribution"><div class="signal-fields"><div><label for="signal-mode">Matching rule</label><select id="signal-mode"><option value="any"${settings.mode==='any'?' selected':''}>Any term in one record</option><option value="all"${settings.mode==='all'?' selected':''}>Every term in one record</option></select></div><div><label for="signal-scope">Geographic scope</label><select id="signal-scope">${['All','Domestic','Cross-border','International'].map(s=>`<option${settings.scope===s?' selected':''}>${s}</option>`).join('')}</select></div><div><label for="signal-from">Reports since</label><input id="signal-from" type="date" value="${settings.from}" required></div><div><label for="signal-to">Known by (as-of date)</label><input id="signal-to" type="date" value="${settings.to}" required></div><div><label for="signal-groups">Source groups for review threshold</label><input id="signal-groups" type="number" min="1" max="10" value="${settings.minGroups}" required></div></div><p class="muted">Publication and recorded dates must both be within the as-of boundary. Corrections known by that date replace superseded excerpts. Distinct recorded groups do not prove independence. Terms are literal text, including in negated sentences.</p><p id="signal-error" class="error" role="alert"></p><div class="actions"><button class="primary" type="submit">Run indicator query</button><button id="compare-reports" type="button">Compare related reports</button></div></form><section class="report-link-section"><h3>Report connections</h3><p><a href="./linkage-lab.html" target="_blank" rel="noopener noreferrer">Inspect retrieval errors in the linkage lab</a></p><div id="report-connections"></div></section><div id="signal-results"></div></div></section>`;result();connections();
  }
  document.addEventListener('submit',event=>{if(event.target.id!=='signal-form')return;event.preventDefault();try{const $=id=>document.getElementById(id),next={terms:$('signal-terms').value,mode:$('signal-mode').value,from:$('signal-from').value,to:$('signal-to').value,minGroups:Number($('signal-groups').value),scope:$('signal-scope').value};const checked=scanSignals(getWorkspace(),next);settings=next;report=checked;$('signal-error').textContent='';result();feedback('Indicator query complete. Review matches in context; no evidence or assessment was changed.');}catch(e){document.getElementById('signal-error').textContent=e.message;}});
  document.addEventListener('click',event=>{if(event.target.closest('button')?.id!=='compare-reports')return;try{const next={from:document.getElementById('signal-from').value,to:document.getElementById('signal-to').value,scope:document.getElementById('signal-scope').value};const checked=compareReports(getWorkspace(),next);comparisonWindow=next;comparison=checked;document.getElementById('signal-error').textContent='';connections();feedback('Report comparison complete. Inspect source passages; no records were merged or changed.');}catch(e){document.getElementById('signal-error').textContent=e.message;}});
  return {render,linkTaskContext(leftId,rightId){if(!comparisonWindow)return null;const current=compareReports(getWorkspace(),comparisonWindow),pair=current.pairs.find(p=>p.left.recordKey===leftId&&p.right.recordKey===rightId);if(!pair)return null;return {assessmentId:pair.left.assessmentId,title:`Verify report relationship: ${pair.left.title}`.slice(0,180),scope:`Compare retained records ${pair.left.id} and ${pair.right.id}, known by ${current.window.to}. Inspect original context, negation, dates, corrections and source dependence. Shared language alone establishes neither event identity nor independent corroboration. Explain whether these are shared reporting, conflicting accounts, unrelated reports or unresolved. Use only permitted material and link reviewed evidence when recording findings.`};},taskContext(assessmentId){if(!report)return null;const current=scanSignals(getWorkspace(),settings),c=current.cases.find(c=>c.assessmentId===assessmentId);if(!c)return null;return {title:`Verify indicator mentions: ${c.title}`.slice(0,180),scope:`Using only authorized source material, compare these recorded matches (${c.recordIds.slice(0,6).join(', ')+(c.recordIds.length>6?' and '+(c.recordIds.length-6)+' more':'')}). Query terms: ${current.query.terms.join(', ')}; known by ${current.query.to}. Check original context, negation, alternative explanations and source independence. Record findings with linked evidence; matching text alone does not establish a threat.`.slice(0,1500)};}};
}
